10:     Attempt, AttemptError, AttemptFailure, ConfigError, Deployment, RouterEvent, RouterHost,
11:     RoutingContext, SelectStage, Served,
12: };
13: 
14: use crate::Gateway;
15: 
16: /// Whether [`NativeRouterHost`] answers `step` as the proxy does. `admit` leaves to Python every
17: /// call that would make a step it does not.
18: pub fn answers(step: &HostStep) -> bool {
19:     match step {
20:         HostStep::Pick(..)
21:         | HostStep::PreCallFacts
22:         | HostStep::HealthStates
23:         | HostStep::FallbackParams(_) => false,
24:     }
25: }
26: 
27: /// router-core's host for one inference call: each attempt runs the request's route, and the
28: /// rest is answered from the gateway's own state.
29: pub struct NativeRouterHost<'a, A> {
30:     pub(super) gateway: &'a Gateway,
31:     pub(super) identity: &'a AuthenticatedRequest,
32:     pub(super) route: &'a A,
33: }
34: 
35: impl<A: RouteAttempt> RouterHost for NativeRouterHost<'_, A> {
36:     type Response = A::Outcome;
37:     type Failure = Error;
38:     type Cache = RoutingCache;
39: 
40:     async fn attempt(
41:         &self,
42:         attempt: &Attempt,
43:     ) -> Result<Served<A::Outcome>, AttemptFailure<Error>> {
44:         routing::attempt(self.gateway, self.route, attempt).await
45:     }
46: 
47:     async fn select(
48:         &self,
49:         _stage: &SelectStage,
50:         _ctx: &RoutingContext<'_>,
51:         _candidates: Vec<Arc<Deployment>>,
52:     ) -> Result<Vec<Arc<Deployment>>, litellm_router_core::Error> {
53:         Err(ConfigError::Unanswered {
54:             step: "a selection stage",
55:         }
56:         .into())
57:     }
58: 
59:     async fn allow_fallback(&self, target: &str) -> Result<bool, AttemptError> {
60:         Ok(routing::allows(self.gateway, self.identity, target).await)
61:     }
62: 
63:     fn cache(&self) -> &RoutingCache {
64:         self.gateway.routing()
65:     }
66: 
67:     async fn sleep(&self, duration: Duration) {
68:         tokio::time::sleep(duration).await;
69:     }
70: 
71:     fn observe(&self, event: &RouterEvent) {
72:         tracing::debug!(target: "litellm::router", ?event, "routing event");
73:     }
74: }
